//! Voice notes: the shared core (docs/VOICE-NOTES.md §5) — a line-for-line port of Tin Hat Web's
//! `src/features/chat/voicenote/core.ts`. Both replay `testvectors/voice-notes/vectors.json` (a byte-identical copy in
//! both repos, generated by an independent reference: `scripts/voice-notes-oracle.py`). Integer maths after one
//! rule-defined f32 → i16 quantisation, so the two sides agree bit for bit. Pure: no Qt, no I/O.

use serde_json::{json, Map, Value};

/// Capture rate both sides record at (Hz).
pub const VOICE_RATE: u32 = 48_000;
/// Samples per level frame: 10 ms at [`VOICE_RATE`].
pub const VOICE_FRAME: usize = 480;
/// Waveform points in the event.
pub const WAVEFORM_N: usize = 100;
/// A frame peak below this never fills the waveform (near-silence stays flat). Same unit as the peaks (0..32768).
pub const WAVEFORM_FLOOR: u32 = 1024;
/// Longest note (ms); recording stops into review on its own. Matches Element's 15 minutes.
pub const VOICE_MAX_MS: u64 = 900_000;
/// "Ending soon" hint this long before the cap.
pub const VOICE_WARN_LEFT_MS: u64 = 10_000;
/// Shorter than this is discarded as a mis-tap.
pub const VOICE_MIN_MS: u64 = 500;
/// The event's body and text fallback.
pub const VOICE_BODY: &str = "Voice message";

/// One sample → i16, by rule: the f32 is widened to f64 and all arithmetic is f64 (what JS does — f32 arithmetic would
/// round differently at the thresholds, see the vectors' "f32 thresholds" case): floor(x·32768 + 0.5) clamped to
/// [-32768, 32767]; NaN → 0.
pub fn quantize(x: f32) -> i32 {
    let v = (x as f64 * 32768.0 + 0.5).floor();
    if v.is_nan() {
        return 0;
    }
    v.clamp(-32768.0, 32767.0) as i32
}

/// Streaming frame peaks: feed sample chunks of any size; one peak (max |i16|, 0..32768) per `frame` samples;
/// [`PeakMeter::finish`] adds the partial last frame. Chunk boundaries never change the result.
#[derive(Debug, Clone)]
pub struct PeakMeter {
    pub frame: usize,
    pub peaks: Vec<u32>,
    pub samples: u64,
    cur: u32,
    n: usize,
}

impl Default for PeakMeter {
    fn default() -> Self {
        Self::new(VOICE_FRAME)
    }
}

impl PeakMeter {
    pub fn new(frame: usize) -> Self {
        Self { frame: frame.max(1), peaks: Vec::new(), samples: 0, cur: 0, n: 0 }
    }
    pub fn push(&mut self, chunk: &[f32]) {
        for &x in chunk {
            let a = quantize(x).unsigned_abs();
            if a > self.cur {
                self.cur = a;
            }
            self.n += 1;
            if self.n == self.frame {
                self.peaks.push(self.cur);
                self.cur = 0;
                self.n = 0;
            }
        }
        self.samples += chunk.len() as u64;
    }
    /// The peak of the frame being filled (the live meter), 0..32768.
    pub fn live(&self) -> u32 {
        if self.n > 0 {
            self.cur
        } else {
            self.peaks.last().copied().unwrap_or(0)
        }
    }
    pub fn finish(&mut self) -> &[u32] {
        if self.n > 0 {
            self.peaks.push(self.cur);
            self.cur = 0;
            self.n = 0;
        }
        &self.peaks
    }
}

/// Integer square root (floor).
pub fn isqrt(x: u64) -> u64 {
    if x == 0 {
        return 0;
    }
    let mut r = (x as f64).sqrt() as u64;
    while r * r > x {
        r -= 1;
    }
    while (r + 1) * (r + 1) <= x {
        r += 1;
    }
    r
}

/// Frame peaks → the event waveform: min(n, frames) points in 0..1024 (see core.ts `waveform`).
pub fn waveform(peaks: &[u32], n: usize) -> Vec<u32> {
    let f = peaks.len();
    if f == 0 || n == 0 {
        return Vec::new();
    }
    let nn = n.min(f);
    let max = peaks.iter().copied().max().unwrap_or(0);
    let denom = max.max(WAVEFORM_FLOOR) as u64;
    (0..nn)
        .map(|i| {
            let lo = i * f / nn;
            let hi = (i + 1) * f / nn;
            let p = peaks[lo..hi].iter().copied().max().unwrap_or(0) as u64;
            isqrt(p * 1_048_576 / denom).min(1024) as u32
        })
        .collect()
}

/// Samples at `rate` → whole milliseconds, half up.
pub fn duration_ms(samples: u64, rate: u32) -> u64 {
    let rate = rate.max(1) as u64;
    (samples * 1000 + rate / 2) / rate
}

/// The base type only, lower case ("audio/webm;codecs=opus" → "audio/webm").
pub fn base_mime(mime: &str) -> String {
    mime.split(';').next().unwrap_or("").trim().to_lowercase()
}

/// "Voice message.<ext>" for the container we send.
pub fn voice_file_name(mime: &str) -> String {
    let ext = match base_mime(mime).as_str() {
        "audio/ogg" => "ogg",
        "audio/webm" => "webm",
        "audio/mp4" => "m4a",
        "audio/mpeg" => "mp3",
        _ => "ogg",
    };
    format!("{VOICE_BODY}.{ext}")
}

/// Where the bytes are: an unencrypted room's mxc, or an encrypted room's EncryptedFile (with its url).
#[derive(Debug, Clone)]
pub enum VoiceMedia {
    Url(String),
    File(Value),
}

/// The m.room.message content of a voice note — Element's createVoiceMessageContent shape (MSC3245 voice + MSC1767
/// audio/file/text), with `url`/`file` per room and the base mimetype.
pub fn voice_content(media: &VoiceMedia, mimetype: &str, size: u64, duration: u64, waveform: &[u32]) -> Value {
    let mime = base_mime(mimetype);
    let mut f = Map::new();
    f.insert("name".into(), json!(voice_file_name(&mime)));
    f.insert("mimetype".into(), json!(mime));
    f.insert("size".into(), json!(size));
    let mut c = Map::new();
    c.insert("msgtype".into(), json!("m.audio"));
    c.insert("body".into(), json!(VOICE_BODY));
    c.insert("info".into(), json!({ "mimetype": mime, "size": size, "duration": duration }));
    c.insert("org.matrix.msc1767.text".into(), json!(VOICE_BODY));
    match media {
        VoiceMedia::File(file) => {
            c.insert("file".into(), file.clone());
            f.insert("file".into(), file.clone());
        }
        VoiceMedia::Url(mxc) => {
            c.insert("url".into(), json!(mxc));
            f.insert("url".into(), json!(mxc));
        }
    }
    c.insert("org.matrix.msc1767.file".into(), Value::Object(f));
    c.insert("org.matrix.msc1767.audio".into(), json!({ "duration": duration, "waveform": waveform }));
    c.insert("org.matrix.msc3245.voice".into(), json!({}));
    Value::Object(c)
}

/// Is this content a voice note (MSC3245)?
pub fn is_voice_note(c: &Value) -> bool {
    c.get("msgtype").and_then(|m| m.as_str()) == Some("m.audio") && c.get("org.matrix.msc3245.voice").is_some()
}

/// Recorded waveform of a received note (0..1024 ints) or None when absent/malformed.
pub fn note_waveform(c: &Value) -> Option<Vec<u32>> {
    let w = c.get("org.matrix.msc1767.audio")?.get("waveform")?.as_array()?;
    if w.is_empty() {
        return None;
    }
    let mut out = Vec::with_capacity(w.len());
    for v in w {
        let x = v.as_f64()?;
        if !x.is_finite() {
            return None;
        }
        // Math.round: half up
        out.push((x + 0.5).floor().clamp(0.0, 1024.0) as u32);
    }
    Some(out)
}

/// m:ss of a duration (the timer and the review chip).
pub fn clock(ms: u64) -> String {
    let s = ms / 1000;
    format!("{}:{:02}", s / 60, s % 60)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn vectors() -> Value {
        let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../testvectors/voice-notes/vectors.json");
        serde_json::from_str(&std::fs::read_to_string(path).expect("vectors")).expect("json")
    }

    fn u32s(v: &Value) -> Vec<u32> {
        v.as_array().unwrap().iter().map(|x| x.as_u64().unwrap() as u32).collect()
    }

    #[test]
    fn constants_are_the_shared_constants() {
        let v = vectors();
        let c = &v["constants"];
        assert_eq!(c["rate"], json!(VOICE_RATE));
        assert_eq!(c["frame"], json!(VOICE_FRAME));
        assert_eq!(c["waveform_n"], json!(WAVEFORM_N));
        assert_eq!(c["floor"], json!(WAVEFORM_FLOOR));
        assert_eq!(c["max_ms"], json!(VOICE_MAX_MS));
        assert_eq!(c["warn_left_ms"], json!(VOICE_WARN_LEFT_MS));
        assert_eq!(c["min_ms"], json!(VOICE_MIN_MS));
        assert_eq!(c["body"], json!(VOICE_BODY));
    }

    #[test]
    fn frame_peaks_chunk_boundaries_never_matter() {
        let v = vectors();
        let cases = v["peaks"].as_array().unwrap();
        assert!(cases.len() >= 8);
        for c in cases {
            let name = c["name"].as_str().unwrap();
            let frame = c["frame"].as_u64().unwrap() as usize;
            let chunks: Vec<Vec<f32>> = c["chunks"]
                .as_array()
                .unwrap()
                .iter()
                .map(|ch| ch.as_array().unwrap().iter().map(|x| x.as_f64().unwrap() as f32).collect())
                .collect();
            let want = u32s(&c["peaks"]);
            let mut m = PeakMeter::new(frame);
            for ch in &chunks {
                m.push(ch);
            }
            assert_eq!(m.finish(), &want[..], "{name}");
            let flat: Vec<f32> = chunks.concat();
            let mut one = PeakMeter::new(frame);
            one.push(&flat);
            assert_eq!(one.finish(), &want[..], "{name} (one chunk)");
            assert_eq!(m.samples, flat.len() as u64);
        }
    }

    #[test]
    fn waveform_matches_the_vectors() {
        let v = vectors();
        let cases = v["waveform"].as_array().unwrap();
        assert!(cases.len() >= 10);
        for c in cases {
            let w = waveform(&u32s(&c["peaks"]), c["n"].as_u64().unwrap() as usize);
            assert_eq!(w, u32s(&c["waveform"]), "{}", c["name"]);
            assert!(w.iter().all(|&x| x <= 1024));
        }
    }

    #[test]
    fn duration_rounding() {
        let v = vectors();
        for c in v["duration"].as_array().unwrap() {
            let got = duration_ms(c["samples"].as_u64().unwrap(), c["rate"].as_u64().unwrap() as u32);
            assert_eq!(got, c["ms"].as_u64().unwrap(), "{c}");
        }
    }

    #[test]
    fn event_content_is_byte_compatible_with_the_web() {
        let v = vectors();
        for c in v["content"].as_array().unwrap() {
            let i = &c["in"];
            let media = match i.get("file") {
                Some(f) => VoiceMedia::File(f.clone()),
                None => VoiceMedia::Url(i["mxc"].as_str().unwrap().to_string()),
            };
            let w = u32s(&i["waveform"]);
            let got = voice_content(
                &media,
                i["mimetype"].as_str().unwrap(),
                i["size"].as_u64().unwrap(),
                i["duration"].as_u64().unwrap(),
                &w,
            );
            assert_eq!(got, c["out"], "{}", c["name"]);
            // canonical bytes too (sorted keys, compact): what both sides put on the wire, modulo key order
            assert_eq!(
                tinhat_theme::canon::canon_json(&got),
                tinhat_theme::canon::canon_json(&c["out"]),
                "{}",
                c["name"]
            );
            assert!(is_voice_note(&got));
            assert_eq!(note_waveform(&got), if w.is_empty() { None } else { Some(w.clone()) });
        }
    }

    #[test]
    fn a_received_waveform_is_clamped_a_malformed_one_ignored() {
        assert_eq!(note_waveform(&json!({"org.matrix.msc1767.audio": {"waveform": [-5, 2000, 511.6]}})), Some(vec![0, 1024, 512]));
        assert_eq!(note_waveform(&json!({"org.matrix.msc1767.audio": {"waveform": ["x"]}})), None);
        assert_eq!(note_waveform(&json!({})), None);
        assert!(!is_voice_note(&json!({"msgtype": "m.audio"})));
        assert_eq!(clock(61_999), "1:01");
        assert_eq!(quantize(f32::NAN), 0);
        assert_eq!(quantize(f32::INFINITY), 32767);
        assert_eq!(quantize(f32::NEG_INFINITY), -32768);
    }
}
